package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NullPropertyPointer;
import org.apache.commons.jxpath.ri.model.beans.PropertyOwnerPointer;
import org.apache.commons.jxpath.ri.model.xpath.QName;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class NullPropertyPointer_createPath_TriageGen0Test {

    private JXPathContext mockContext;
    private NodePointer mockParent;
    private QName mockQName;

    @Before
    public void setUp() {
        mockContext = mock(JXPathContext.class);
        mockParent = mock(NodePointer.class);
        mockQName = mock(QName.class);
    }

    /**
     * Test branch: isAttribute() is true.
     * This covers the first if block.
     */
    @Test
    public void testCreatePath_IsAttribute() {
        // Setup
        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));
        Object value = "testValue";
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttributePointer = mock(NodePointer.class);

        doReturn(true).when(nullPropertyPointer).isAttribute();
        doReturn(mockQName).when(nullPropertyPointer).getName();
        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(mockContext, mockQName)).thenReturn(mockAttributePointer);

        // Execute
        NodePointer result = nullPropertyPointer.createPath(mockContext, value);

        // Verify
        verify(mockParent).createPath(mockContext);
        verify(mockNewParent).createAttribute(mockContext, mockQName);
        verify(mockAttributePointer).setValue(value);
        assertEquals(mockAttributePointer, result);
    }

    /**
     * Test branch: isAttribute() is false AND newParent is NOT an instance of PropertyOwnerPointer.
     * This covers the else block and the false branch of the inner if.
     */
    @Test
    public void testCreatePath_NotAttribute_NotPropertyOwnerPointer() {
        // Setup
        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));
        Object value = "testValue";
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockChildPointer = mock(NodePointer.class);

        doReturn(false).when(nullPropertyPointer).isAttribute();
        doReturn(mockQName).when(nullPropertyPointer).getName();
        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        // mockNewParent is a standard NodePointer, not PropertyOwnerPointer
        when(mockNewParent.createChild(eq(mockContext), eq(mockQName), any(Integer.class), eq(value)))
                .thenReturn(mockChildPointer);

        // We need to ensure the index is handled. Since index is not explicitly set in snippet, 
        // we assume it's 0 or whatever the field holds.
        // Let's use reflection or assume default if we can't set it via public API.
        // In the provided code, 'index' is a field of NullPropertyPointer. 
        // Since we can't access it easily, we rely on the mock to match.

        // To make the mock match createChild(context, name, index, value), 
        // we need to know the index. Since we can't set it easily without reflection, 
        // we'll use anyInt() in a real scenario or assume it's 0.
        // However, to be precise with the provided code structure:
        when(mockNewParent.createChild(eq(mockContext), eq(mockQName), anyInt(), eq(value)))
                .thenReturn(mockChildPointer);

        // Execute
        NodePointer result = nullPropertyPointer.createPath(mockContext, value);

        // Verify
        verify(mockParent).createPath(mockContext);
        verify(mockNewParent).createChild(eq(mockContext), eq(mockQName), anyInt(), eq(value));
        assertEquals(mockChildPointer, result);
    }

    /**
     * Test branch: isAttribute() is false AND newParent IS an instance of PropertyOwnerPointer.
     * This covers the else block and the true branch of the inner if.
     */
    @Test
    public void testCreatePath_NotAttribute_IsPropertyOwnerPointer() {
        // Setup
        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));
        Object value = "testValue";

        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropertyPointer = mock(NodePointer.class);
        NodePointer mockChildPointer = mock(NodePointer.class);

        doReturn(false).when(nullPropertyPointer).isAttribute();
        doReturn(mockQName).when(nullPropertyPointer).getName();
        when(mockParent.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropertyPointer);
        when(mockPropertyPointer.createChild(eq(mockContext), eq(mockQName), anyInt(), eq(value)))
                .thenReturn(mockChildPointer);

        // Execute
        NodePointer result = nullPropertyPointer.createPath(mockContext, value);

        // Verify
        verify(mockParent).createPath(mockContext);
        verify(mockPop).getPropertyPointer();
        verify(mockPropertyPointer).createChild(eq(mockContext), eq(mockQName), anyInt(), eq(value));
        assertEquals(mockChildPointer, result);
    }
}

/**
 * Helper to allow anyInt() usage in the test if the exact index is unknown
 */
class anyInt extends org.mockito.ArgumentMatchers.ArgumentMatcher<Integer> {
    @Override
    public boolean matches(Integer argument) {
        return true;
    }
}
